-- Reejecutable. Solo añade o actualiza estas dos rondas; no elimina otras evaluaciones.

begin;











































commit;

select e.titulo,count(p.id) as preguntas,count(p.id) filter (where coalesce(p.opciones->0->>'pregunta_imagen','') <> '') as con_imagen from public.evaluaciones e join public.evaluacion_preguntas p on p.evaluacion_id=e.id where e.id in ('7d7b8eaa-4b8e-51cb-a9db-a666bda3d976','2fa17a3c-035a-50d7-afae-ed8fe3ba11fc') group by e.id,e.titulo order by e.titulo;
