insert into public.evaluaciones (id,titulo,asignatura,nivel,idioma,visibilidad,objetivo,codigo,publicado,created_by,created_at,updated_at,iniciado,tema,modo_sesion,config_juego) values ('7d7b8eaa-4b8e-51cb-a9db-a666bda3d976','Sentidos Saladin — Ronda 1: Receptores, dolor, gusto y olfato (20 preguntas fáciles)','MORFOFUNCION','Residencia','espanol','publica','Contenido exclusivamente de la presentación aportada. Dos rondas de 20 preguntas con imágenes extraídas de la misma presentación.','SENTIDOS1',true,'dd2eed5d-b917-4c4d-b0e7-aa6b1e57ef23',now(),now(),true,'Sentidos Saladin: Receptores, dolor, gusto y olfato','individual','{"maxQuestions":20,"questionOrder":["0324bcfe-78f0-589e-a306-a4a10d8942ed","bc8f73a2-98aa-53e2-ac37-1c4fd80fcdca","64ba0b41-8bf1-57de-a0e9-a59ab6d5a94f","b0b121ef-1958-552c-9ae9-ea0383d0a677","e99941f6-d43c-54e0-bc2e-65a3db1feeca","33d04ce0-665e-5936-86bd-d642a1822d19","92650d10-b371-525e-880c-b1eed8c91846","8c9dce87-1d5f-51a1-a228-ba3beefd46d0","a6fec7f1-7be2-5a9f-85aa-938638f1f431","f1a63054-6083-5a25-bf62-49e661c6349e","0b03bc69-b531-52be-b978-b0073708f00f","93e7a65b-0d23-564a-9259-6484a10ae3b4","b470cf25-cf2a-51d6-95ec-185d1a41f154","68eca636-19a9-5379-96a9-8752431b6170","bebe3743-20c9-5afb-91da-5a5209fc66d4","acae1ba3-353d-595d-8963-c80e1810905a","cbaa77e7-e8ea-5498-8b31-6b9fa53f07c8","486650a2-7285-5032-917f-acfd0f0ab17c","e3933802-3760-5515-b130-501345046d78","8c8e4300-e05d-5b62-8a71-7073782eead0"],"enabledPowerups":["x2","time","retry"]}'::jsonb) on conflict(id) do update set titulo=excluded.titulo,tema=excluded.tema,objetivo=excluded.objetivo,publicado=true,iniciado=true,config_juego=excluded.config_juego,updated_at=now();
insert into public.evaluacion_preguntas (id,evaluacion_id,tipo,texto,opciones,multiple_correctas,orden,puntos,temporizador) values ('0324bcfe-78f0-589e-a306-a4a10d8942ed','7d7b8eaa-4b8e-51cb-a9db-a666bda3d976','mc','¿Qué proceso convierte la energía de un estímulo en señales nerviosas?','[{"text":"Adaptación","correct":false,"pregunta_imagen":"/juegos/assets/sentidos-saladin/s2-image7.png","explicacion":"La transducción es la conversión de la energía del estímulo en señales nerviosas. Fuente: diapositiva 3."},{"text":"Transducción","correct":true},{"text":"Acomodación","correct":false},{"text":"Convergencia","correct":false}]'::jsonb,false,1,1,60) on conflict(id) do update set tipo=excluded.tipo,texto=excluded.texto,opciones=excluded.opciones,multiple_correctas=excluded.multiple_correctas,orden=excluded.orden,puntos=excluded.puntos,temporizador=excluded.temporizador;
insert into public.evaluacion_preguntas (id,evaluacion_id,tipo,texto,opciones,multiple_correctas,orden,puntos,temporizador) values ('bc8f73a2-98aa-53e2-ac37-1c4fd80fcdca','7d7b8eaa-4b8e-51cb-a9db-a666bda3d976','ms','¿Cuáles son sentidos especiales? Selecciona todas las respuestas correctas.','[{"text":"Visión","correct":true,"pregunta_imagen":"/juegos/assets/sentidos-saladin/s7-image26.png","explicacion":"Los sentidos especiales son visión, audición, equilibrio, gusto y olfato. El tacto pertenece a los sentidos generales. Fuente: diapositiva 10."},{"text":"Audición","correct":true},{"text":"Gusto","correct":true},{"text":"Olfato","correct":true},{"text":"Equilibrio","correct":true},{"text":"Tacto de la piel","correct":false}]'::jsonb,true,2,1,60) on conflict(id) do update set tipo=excluded.tipo,texto=excluded.texto,opciones=excluded.opciones,multiple_correctas=excluded.multiple_correctas,orden=excluded.orden,puntos=excluded.puntos,temporizador=excluded.temporizador;
insert into public.evaluacion_preguntas (id,evaluacion_id,tipo,texto,opciones,multiple_correctas,orden,puntos,temporizador) values ('64ba0b41-8bf1-57de-a0e9-a59ab6d5a94f','7d7b8eaa-4b8e-51cb-a9db-a666bda3d976','tf','Todas las señales sensitivas que llegan al sistema nervioso central producen una sensación consciente.','[{"text":"Verdadero","correct":false,"pregunta_imagen":"/juegos/assets/sentidos-saladin/s3-image9.png","explicacion":"Muchas señales se filtran o participan en funciones que no requieren conciencia. Fuente: diapositiva 3."},{"text":"Falso","correct":true}]'::jsonb,false,3,1,60) on conflict(id) do update set tipo=excluded.tipo,texto=excluded.texto,opciones=excluded.opciones,multiple_correctas=excluded.multiple_correctas,orden=excluded.orden,puntos=excluded.puntos,temporizador=excluded.temporizador;
insert into public.evaluacion_preguntas (id,evaluacion_id,tipo,texto,opciones,multiple_correctas,orden,puntos,temporizador) values ('b0b121ef-1958-552c-9ae9-ea0383d0a677','7d7b8eaa-4b8e-51cb-a9db-a666bda3d976','mc','¿Qué sentido te permite notar que alguien toca tu mano?','[{"text":"Tacto","correct":true,"pregunta_imagen":"/juegos/assets/sentidos-saladin/s18-image73.png","explicacion":"Los receptores de la piel permiten detectar el contacto. Fuente: diapositiva 13."},{"text":"Gusto","correct":false},{"text":"Olfato","correct":false},{"text":"Visión","correct":false}]'::jsonb,false,4,1,60) on conflict(id) do update set tipo=excluded.tipo,texto=excluded.texto,opciones=excluded.opciones,multiple_correctas=excluded.multiple_correctas,orden=excluded.orden,puntos=excluded.puntos,temporizador=excluded.temporizador;
insert into public.evaluacion_preguntas (id,evaluacion_id,tipo,texto,opciones,multiple_correctas,orden,puntos,temporizador) values ('e99941f6-d43c-54e0-bc2e-65a3db1feeca','7d7b8eaa-4b8e-51cb-a9db-a666bda3d976','match','Relaciona cada receptor con el estímulo que detecta.','[{"text":"Termorreceptor","match":"Frío o calor","pregunta_imagen":"/juegos/assets/sentidos-saladin/s2-image6.png","explicacion":"Los receptores se clasifican según la modalidad de estímulo a la que responden. Fuente: diapositiva 10."},{"text":"Fotorreceptor","match":"Luz"},{"text":"Quimiorreceptor","match":"Sustancias químicas"},{"text":"Mecanorreceptor","match":"Deformación física"}]'::jsonb,false,5,1,90) on conflict(id) do update set tipo=excluded.tipo,texto=excluded.texto,opciones=excluded.opciones,multiple_correctas=excluded.multiple_correctas,orden=excluded.orden,puntos=excluded.puntos,temporizador=excluded.temporizador;
insert into public.evaluacion_preguntas (id,evaluacion_id,tipo,texto,opciones,multiple_correctas,orden,puntos,temporizador) values ('33d04ce0-665e-5936-86bd-d642a1822d19','7d7b8eaa-4b8e-51cb-a9db-a666bda3d976','mc','Un olor se percibe con fuerza al principio y luego deja de notarse aunque siga presente. ¿Qué propiedad lo explica?','[{"text":"Adaptación lenta de receptores tónicos","correct":false,"pregunta_imagen":"/juegos/assets/sentidos-saladin/s8-image29.png","explicacion":"Los receptores fásicos se adaptan con rapidez y reducen sus señales aunque el estímulo continúe. Fuente: diapositiva 7."},{"text":"Ausencia de transducción","correct":false},{"text":"Adaptación rápida de receptores fásicos","correct":true},{"text":"Aumento progresivo de la intensidad del estímulo","correct":false}]'::jsonb,false,6,1,60) on conflict(id) do update set tipo=excluded.tipo,texto=excluded.texto,opciones=excluded.opciones,multiple_correctas=excluded.multiple_correctas,orden=excluded.orden,puntos=excluded.puntos,temporizador=excluded.temporizador;
insert into public.evaluacion_preguntas (id,evaluacion_id,tipo,texto,opciones,multiple_correctas,orden,puntos,temporizador) values ('92650d10-b371-525e-880c-b1eed8c91846','7d7b8eaa-4b8e-51cb-a9db-a666bda3d976','tf','La propiocepción informa sobre la posición y el movimiento de nuestro cuerpo.','[{"text":"Verdadero","correct":true,"pregunta_imagen":"/juegos/assets/sentidos-saladin/s8-image31.png","explicacion":"Los propiorreceptores detectan la posición y el movimiento corporal. Se encuentran en músculos, tendones y cápsulas articulares. Fuente: diapositiva 10."},{"text":"Falso","correct":false}]'::jsonb,false,7,1,60) on conflict(id) do update set tipo=excluded.tipo,texto=excluded.texto,opciones=excluded.opciones,multiple_correctas=excluded.multiple_correctas,orden=excluded.orden,puntos=excluded.puntos,temporizador=excluded.temporizador;
insert into public.evaluacion_preguntas (id,evaluacion_id,tipo,texto,opciones,multiple_correctas,orden,puntos,temporizador) values ('8c9dce87-1d5f-51a1-a228-ba3beefd46d0','7d7b8eaa-4b8e-51cb-a9db-a666bda3d976','match','Relaciona cada grupo de receptores con el origen de la información.','[{"text":"Exterorreceptores","match":"Estímulos externos al cuerpo","pregunta_imagen":"/juegos/assets/sentidos-saladin/s10-image42.png","explicacion":"La clasificación por origen distingue estímulos externos, internos y de posición corporal. Fuente: diapositiva 10."},{"text":"Interorreceptores","match":"Estímulos de los órganos internos"},{"text":"Propiorreceptores","match":"Posición y movimiento del cuerpo"}]'::jsonb,false,8,1,90) on conflict(id) do update set tipo=excluded.tipo,texto=excluded.texto,opciones=excluded.opciones,multiple_correctas=excluded.multiple_correctas,orden=excluded.orden,puntos=excluded.puntos,temporizador=excluded.temporizador;
insert into public.evaluacion_preguntas (id,evaluacion_id,tipo,texto,opciones,multiple_correctas,orden,puntos,temporizador) values ('a6fec7f1-7be2-5a9f-85aa-938638f1f431','7d7b8eaa-4b8e-51cb-a9db-a666bda3d976','ms','¿Dónde se encuentran receptores de los sentidos generales?','[{"text":"Piel","correct":true,"pregunta_imagen":"/juegos/assets/sentidos-saladin/s18-image72.png","explicacion":"Los sentidos generales emplean receptores distribuidos en piel, músculos, tendones y otros tejidos. Fuente: diapositiva 10."},{"text":"Músculos","correct":true},{"text":"Tendones","correct":true},{"text":"Únicamente en los ojos","correct":false}]'::jsonb,true,9,1,60) on conflict(id) do update set tipo=excluded.tipo,texto=excluded.texto,opciones=excluded.opciones,multiple_correctas=excluded.multiple_correctas,orden=excluded.orden,puntos=excluded.puntos,temporizador=excluded.temporizador;
insert into public.evaluacion_preguntas (id,evaluacion_id,tipo,texto,opciones,multiple_correctas,orden,puntos,temporizador) values ('f1a63054-6083-5a25-bf62-49e661c6349e','7d7b8eaa-4b8e-51cb-a9db-a666bda3d976','mc','¿Qué receptores detectan que un contacto ligero dobla un pelo?','[{"text":"Fotorreceptores","correct":false,"pregunta_imagen":"/juegos/assets/sentidos-saladin/s8-image30.png","explicacion":"Los receptores pilosos tienen dendritas alrededor de la base del folículo y responden al movimiento del pelo. Fuente: diapositiva 15."},{"text":"Receptores pilosos","correct":true},{"text":"Corpúsculos bulbosos","correct":false},{"text":"Células gustativas","correct":false}]'::jsonb,false,10,1,60) on conflict(id) do update set tipo=excluded.tipo,texto=excluded.texto,opciones=excluded.opciones,multiple_correctas=excluded.multiple_correctas,orden=excluded.orden,puntos=excluded.puntos,temporizador=excluded.temporizador;
insert into public.evaluacion_preguntas (id,evaluacion_id,tipo,texto,opciones,multiple_correctas,orden,puntos,temporizador) values ('0b03bc69-b531-52be-b978-b0073708f00f','7d7b8eaa-4b8e-51cb-a9db-a666bda3d976','match','Relaciona cada estructura con el sentido correspondiente.','[{"text":"Piel","match":"Tacto","pregunta_imagen":"/juegos/assets/sentidos-saladin/s9-image37.png","explicacion":"La presentación relaciona los órganos sensoriales con los estímulos que perciben. Fuente: diapositiva 2."},{"text":"Ojos","match":"Visión"},{"text":"Nariz","match":"Olfato"},{"text":"Lengua","match":"Gusto"}]'::jsonb,false,11,1,90) on conflict(id) do update set tipo=excluded.tipo,texto=excluded.texto,opciones=excluded.opciones,multiple_correctas=excluded.multiple_correctas,orden=excluded.orden,puntos=excluded.puntos,temporizador=excluded.temporizador;
insert into public.evaluacion_preguntas (id,evaluacion_id,tipo,texto,opciones,multiple_correctas,orden,puntos,temporizador) values ('93e7a65b-0d23-564a-9259-6484a10ae3b4','7d7b8eaa-4b8e-51cb-a9db-a666bda3d976','tf','Los receptores del dolor responden a una lesión tisular o a situaciones que amenazan con dañar los tejidos.','[{"text":"Verdadero","correct":true,"pregunta_imagen":"/juegos/assets/sentidos-saladin/s9-image34.png","explicacion":"Los receptores del dolor detectan daño tisular real o potencial. Fuente: diapositiva 10."},{"text":"Falso","correct":false}]'::jsonb,false,12,1,60) on conflict(id) do update set tipo=excluded.tipo,texto=excluded.texto,opciones=excluded.opciones,multiple_correctas=excluded.multiple_correctas,orden=excluded.orden,puntos=excluded.puntos,temporizador=excluded.temporizador;
insert into public.evaluacion_preguntas (id,evaluacion_id,tipo,texto,opciones,multiple_correctas,orden,puntos,temporizador) values ('b470cf25-cf2a-51d6-95ec-185d1a41f154','7d7b8eaa-4b8e-51cb-a9db-a666bda3d976','mc','¿Qué es el dolor referido?','[{"text":"Dolor que solo aparece durante el sueño","correct":false,"pregunta_imagen":"/juegos/assets/sentidos-saladin/s26-image96.png","explicacion":"En el dolor referido, el dolor se percibe en una región diferente de donde se origina la señal. Fuente: diapositiva 29."},{"text":"Ausencia total de dolor","correct":false},{"text":"Dolor que siempre se siente justo donde se origina","correct":false},{"text":"Dolor que se percibe en un lugar distinto de su origen","correct":true}]'::jsonb,false,13,1,60) on conflict(id) do update set tipo=excluded.tipo,texto=excluded.texto,opciones=excluded.opciones,multiple_correctas=excluded.multiple_correctas,orden=excluded.orden,puntos=excluded.puntos,temporizador=excluded.temporizador;
insert into public.evaluacion_preguntas (id,evaluacion_id,tipo,texto,opciones,multiple_correctas,orden,puntos,temporizador) values ('68eca636-19a9-5379-96a9-8752431b6170','7d7b8eaa-4b8e-51cb-a9db-a666bda3d976','ms','Selecciona los cinco sabores primarios reconocidos en la presentación.','[{"text":"Dulce","correct":true,"pregunta_imagen":"/juegos/assets/sentidos-saladin/s38-image133.png","explicacion":"Los cinco sabores son dulce, salado, ácido, amargo y umami. Crujiente describe una textura. Fuente: diapositiva 38."},{"text":"Salado","correct":true},{"text":"Ácido","correct":true},{"text":"Amargo","correct":true},{"text":"Umami","correct":true},{"text":"Crujiente","correct":false}]'::jsonb,true,14,1,60) on conflict(id) do update set tipo=excluded.tipo,texto=excluded.texto,opciones=excluded.opciones,multiple_correctas=excluded.multiple_correctas,orden=excluded.orden,puntos=excluded.puntos,temporizador=excluded.temporizador;
insert into public.evaluacion_preguntas (id,evaluacion_id,tipo,texto,opciones,multiple_correctas,orden,puntos,temporizador) values ('bebe3743-20c9-5afb-91da-5a5209fc66d4','7d7b8eaa-4b8e-51cb-a9db-a666bda3d976','mc','¿Qué sabor se describe como «a carne» y se relaciona con aminoácidos como el glutámico?','[{"text":"Ácido","correct":false,"pregunta_imagen":"/juegos/assets/sentidos-saladin/s39-image136.png","explicacion":"El umami se relaciona con aminoácidos como los ácidos glutámico y aspártico. Fuente: diapositiva 39."},{"text":"Salado","correct":false},{"text":"Umami","correct":true},{"text":"Amargo","correct":false}]'::jsonb,false,15,1,60) on conflict(id) do update set tipo=excluded.tipo,texto=excluded.texto,opciones=excluded.opciones,multiple_correctas=excluded.multiple_correctas,orden=excluded.orden,puntos=excluded.puntos,temporizador=excluded.temporizador;
insert into public.evaluacion_preguntas (id,evaluacion_id,tipo,texto,opciones,multiple_correctas,orden,puntos,temporizador) values ('acae1ba3-353d-595d-8963-c80e1810905a','7d7b8eaa-4b8e-51cb-a9db-a666bda3d976','tf','Las papilas filiformes desempeñan un papel gustativo porque contienen botones gustativos.','[{"text":"Verdadero","correct":false,"pregunta_imagen":"/juegos/assets/sentidos-saladin/s35-image121.jpg","explicacion":"Las papilas filiformes son abundantes, pero la presentación indica que no tienen función gustativa. Fuente: diapositiva 35."},{"text":"Falso","correct":true}]'::jsonb,false,16,1,60) on conflict(id) do update set tipo=excluded.tipo,texto=excluded.texto,opciones=excluded.opciones,multiple_correctas=excluded.multiple_correctas,orden=excluded.orden,puntos=excluded.puntos,temporizador=excluded.temporizador;
insert into public.evaluacion_preguntas (id,evaluacion_id,tipo,texto,opciones,multiple_correctas,orden,puntos,temporizador) values ('cbaa77e7-e8ea-5498-8b31-6b9fa53f07c8','7d7b8eaa-4b8e-51cb-a9db-a666bda3d976','match','Relaciona cada sabor con el estímulo descrito en la presentación.','[{"text":"Salado","match":"Iones metálicos, como sodio y potasio","pregunta_imagen":"/juegos/assets/sentidos-saladin/s39-image135.png","explicacion":"El sabor salado corresponde a iones metálicos; el ácido, a ácidos; el umami, a determinados aminoácidos. Fuente: diapositiva 38."},{"text":"Ácido","match":"Ácidos"},{"text":"Umami","match":"Aminoácidos, como glutámico y aspártico"}]'::jsonb,false,17,1,90) on conflict(id) do update set tipo=excluded.tipo,texto=excluded.texto,opciones=excluded.opciones,multiple_correctas=excluded.multiple_correctas,orden=excluded.orden,puntos=excluded.puntos,temporizador=excluded.temporizador;
insert into public.evaluacion_preguntas (id,evaluacion_id,tipo,texto,opciones,multiple_correctas,orden,puntos,temporizador) values ('486650a2-7285-5032-917f-acfd0f0ab17c','7d7b8eaa-4b8e-51cb-a9db-a666bda3d976','mc','¿Qué diferencia a las células olfativas de las células gustativas?','[{"text":"Las olfativas son neuronas y las gustativas son células epiteliales","correct":true,"pregunta_imagen":"/juegos/assets/sentidos-saladin/s3-image10.png","explicacion":"La presentación identifica las células olfativas como neuronas y las gustativas como células epiteliales. Fuente: diapositiva 40."},{"text":"Ambas son exclusivamente células musculares","correct":false},{"text":"Las gustativas son neuronas y las olfativas son células óseas","correct":false},{"text":"Ninguna se relaciona con fibras nerviosas","correct":false}]'::jsonb,false,18,1,60) on conflict(id) do update set tipo=excluded.tipo,texto=excluded.texto,opciones=excluded.opciones,multiple_correctas=excluded.multiple_correctas,orden=excluded.orden,puntos=excluded.puntos,temporizador=excluded.temporizador;
insert into public.evaluacion_preguntas (id,evaluacion_id,tipo,texto,opciones,multiple_correctas,orden,puntos,temporizador) values ('e3933802-3760-5515-b130-501345046d78','7d7b8eaa-4b8e-51cb-a9db-a666bda3d976','ms','¿Qué afirmaciones sobre las células gustativas son correctas?','[{"text":"Son células epiteliales","correct":true,"pregunta_imagen":"/juegos/assets/sentidos-saladin/s41-image141.jpg","explicacion":"Las células gustativas son epiteliales y liberan neurotransmisores hacia fibras sensitivas. Fuente: diapositiva 35."},{"text":"Se conectan mediante sinapsis con fibras sensitivas","correct":true},{"text":"Liberan neurotransmisores","correct":true},{"text":"Son los axones del nervio óptico","correct":false}]'::jsonb,true,19,1,60) on conflict(id) do update set tipo=excluded.tipo,texto=excluded.texto,opciones=excluded.opciones,multiple_correctas=excluded.multiple_correctas,orden=excluded.orden,puntos=excluded.puntos,temporizador=excluded.temporizador;
insert into public.evaluacion_preguntas (id,evaluacion_id,tipo,texto,opciones,multiple_correctas,orden,puntos,temporizador) values ('8c8e4300-e05d-5b62-8a71-7073782eead0','7d7b8eaa-4b8e-51cb-a9db-a666bda3d976','mc','¿En qué región se encuentra el epitelio que detecta los olores?','[{"text":"En la lengua","correct":false,"pregunta_imagen":"/juegos/assets/sentidos-saladin/s51-image160.png","explicacion":"El epitelio olfativo se encuentra en la región superior de la cavidad nasal. Fuente: diapositiva 40."},{"text":"En la parte superior de la cavidad nasal","correct":true},{"text":"En el oído medio","correct":false},{"text":"En la córnea","correct":false}]'::jsonb,false,20,1,60) on conflict(id) do update set tipo=excluded.tipo,texto=excluded.texto,opciones=excluded.opciones,multiple_correctas=excluded.multiple_correctas,orden=excluded.orden,puntos=excluded.puntos,temporizador=excluded.temporizador;
insert into public.evaluaciones (id,titulo,asignatura,nivel,idioma,visibilidad,objetivo,codigo,publicado,created_by,created_at,updated_at,iniciado,tema,modo_sesion,config_juego) values ('2fa17a3c-035a-50d7-afae-ed8fe3ba11fc','Sentidos Saladin — Ronda 2: Audición, equilibrio y visión (20 preguntas fáciles)','MORFOFUNCION','Residencia','espanol','publica','Contenido exclusivamente de la presentación aportada. Dos rondas de 20 preguntas con imágenes extraídas de la misma presentación.','SENTIDOS2',true,'dd2eed5d-b917-4c4d-b0e7-aa6b1e57ef23',now(),now(),true,'Sentidos Saladin: Audición, equilibrio y visión','individual','{"maxQuestions":20,"questionOrder":["821bf597-3ceb-5579-8143-d8aacab78de5","4aed3f45-94e0-5120-a75f-fc0ff4627916","ae5fa77d-b86e-5925-a72a-e3c7a244c534","78f29a1e-d0f3-5ad7-85a7-924c581b957c","a9aa1bde-fe3f-59d1-9ff3-742773bf4bc7","f730b0ea-fd03-5e68-b80e-f4cd199728a1","dbdf5e1d-33df-5e8b-bc26-c021a813eed8","7af3994a-eaf5-5954-90a2-503ccb523da7","8a2ecbee-fc66-5676-838d-e7d829be9551","0400dd5f-21e3-5829-86c8-7cedc655a4dc","22b2438c-ad4a-5a64-a380-1803bdb9db72","fa546b6e-8fcc-5c43-bb43-41c6fe4d6066","aece70ef-22d9-5353-8d1b-b7673d3952b1","0dff4ac3-c04a-541c-9729-876984a49c8c","ef64e77e-a5f9-56b8-9d7a-c1374e4f63fe","3006dbc3-78cd-571c-aca0-8b136a740e8f","50d49340-8dad-5a1d-a77a-139906741d2f","42ca4ec0-4c38-5cd0-b6e8-a3bda0e29335","98195178-b98c-5820-a39b-9c4d2da1acea","9f1d594c-3413-58e5-b63a-e59f0cc8be6e"],"enabledPowerups":["x2","time","retry"]}'::jsonb) on conflict(id) do update set titulo=excluded.titulo,tema=excluded.tema,objetivo=excluded.objetivo,publicado=true,iniciado=true,config_juego=excluded.config_juego,updated_at=now();
insert into public.evaluacion_preguntas (id,evaluacion_id,tipo,texto,opciones,multiple_correctas,orden,puntos,temporizador) values ('821bf597-3ceb-5579-8143-d8aacab78de5','2fa17a3c-035a-50d7-afae-ed8fe3ba11fc','mc','¿Cuál es el orden de los huesecillos desde la membrana timpánica hacia el oído interno?','[{"text":"Estribo, yunque, martillo","correct":false,"pregunta_imagen":"/juegos/assets/sentidos-saladin/s61-image192.png","explicacion":"Desde fuera hacia dentro se encuentran martillo, yunque y estribo. Fuente: diapositiva 58."},{"text":"Yunque, martillo, estribo","correct":false},{"text":"Martillo, yunque, estribo","correct":true},{"text":"Martillo, estribo, yunque","correct":false}]'::jsonb,false,1,1,60) on conflict(id) do update set tipo=excluded.tipo,texto=excluded.texto,opciones=excluded.opciones,multiple_correctas=excluded.multiple_correctas,orden=excluded.orden,puntos=excluded.puntos,temporizador=excluded.temporizador;
insert into public.evaluacion_preguntas (id,evaluacion_id,tipo,texto,opciones,multiple_correctas,orden,puntos,temporizador) values ('4aed3f45-94e0-5120-a75f-fc0ff4627916','2fa17a3c-035a-50d7-afae-ed8fe3ba11fc','tf','La trompa auditiva ayuda a igualar la presión a ambos lados de la membrana timpánica.','[{"text":"Verdadero","correct":true,"pregunta_imagen":"/juegos/assets/sentidos-saladin/s60-image189.png","explicacion":"Al abrirse durante la deglución o el bostezo, permite el intercambio de aire con la cavidad timpánica. Fuente: diapositiva 58."},{"text":"Falso","correct":false}]'::jsonb,false,2,1,60) on conflict(id) do update set tipo=excluded.tipo,texto=excluded.texto,opciones=excluded.opciones,multiple_correctas=excluded.multiple_correctas,orden=excluded.orden,puntos=excluded.puntos,temporizador=excluded.temporizador;
insert into public.evaluacion_preguntas (id,evaluacion_id,tipo,texto,opciones,multiple_correctas,orden,puntos,temporizador) values ('ae5fa77d-b86e-5925-a72a-e3c7a244c534','2fa17a3c-035a-50d7-afae-ed8fe3ba11fc','ms','¿Cuáles son los tres huesecillos del oído medio?','[{"text":"Martillo","correct":true,"pregunta_imagen":"/juegos/assets/sentidos-saladin/s71-image217.png","explicacion":"Martillo, yunque y estribo forman la cadena de huesecillos. La cóclea pertenece al oído interno. Fuente: diapositiva 58."},{"text":"Yunque","correct":true},{"text":"Estribo","correct":true},{"text":"Cóclea","correct":false}]'::jsonb,true,3,1,60) on conflict(id) do update set tipo=excluded.tipo,texto=excluded.texto,opciones=excluded.opciones,multiple_correctas=excluded.multiple_correctas,orden=excluded.orden,puntos=excluded.puntos,temporizador=excluded.temporizador;
insert into public.evaluacion_preguntas (id,evaluacion_id,tipo,texto,opciones,multiple_correctas,orden,puntos,temporizador) values ('78f29a1e-d0f3-5ad7-85a7-924c581b957c','2fa17a3c-035a-50d7-afae-ed8fe3ba11fc','mc','¿En qué abertura se encuentra la base del estribo?','[{"text":"Ventana redonda","correct":false,"pregunta_imagen":"/juegos/assets/sentidos-saladin/s70-image213.png","explicacion":"La base del estribo ocupa la ventana oval, donde comienza el oído interno. Fuente: diapositiva 61."},{"text":"Conducto auditivo externo","correct":false},{"text":"Trompa auditiva","correct":false},{"text":"Ventana oval","correct":true}]'::jsonb,false,4,1,60) on conflict(id) do update set tipo=excluded.tipo,texto=excluded.texto,opciones=excluded.opciones,multiple_correctas=excluded.multiple_correctas,orden=excluded.orden,puntos=excluded.puntos,temporizador=excluded.temporizador;
insert into public.evaluacion_preguntas (id,evaluacion_id,tipo,texto,opciones,multiple_correctas,orden,puntos,temporizador) values ('a9aa1bde-fe3f-59d1-9ff3-742773bf4bc7','2fa17a3c-035a-50d7-afae-ed8fe3ba11fc','match','Relaciona cada estructura con la región del oído a la que pertenece.','[{"text":"Conducto auditivo externo","match":"Oído externo","pregunta_imagen":"/juegos/assets/sentidos-saladin/s53-image163.jpg","explicacion":"La presentación organiza el oído en externo, medio e interno. Fuente: diapositiva 61."},{"text":"Cadena de huesecillos","match":"Oído medio"},{"text":"Cóclea","match":"Oído interno"}]'::jsonb,false,5,1,90) on conflict(id) do update set tipo=excluded.tipo,texto=excluded.texto,opciones=excluded.opciones,multiple_correctas=excluded.multiple_correctas,orden=excluded.orden,puntos=excluded.puntos,temporizador=excluded.temporizador;
insert into public.evaluacion_preguntas (id,evaluacion_id,tipo,texto,opciones,multiple_correctas,orden,puntos,temporizador) values ('f730b0ea-fd03-5e68-b80e-f4cd199728a1','2fa17a3c-035a-50d7-afae-ed8fe3ba11fc','mc','¿Cuál es la función del órgano de Corti?','[{"text":"Producir lágrimas","correct":false,"pregunta_imagen":"/juegos/assets/sentidos-saladin/s79-image235.jpg","explicacion":"El órgano de Corti convierte las vibraciones en señales nerviosas relacionadas con la audición. Fuente: diapositiva 65."},{"text":"Convertir vibraciones en señales nerviosas para la audición","correct":true},{"text":"Detectar sabores","correct":false},{"text":"Cambiar el color del iris","correct":false}]'::jsonb,false,6,1,60) on conflict(id) do update set tipo=excluded.tipo,texto=excluded.texto,opciones=excluded.opciones,multiple_correctas=excluded.multiple_correctas,orden=excluded.orden,puntos=excluded.puntos,temporizador=excluded.temporizador;
insert into public.evaluacion_preguntas (id,evaluacion_id,tipo,texto,opciones,multiple_correctas,orden,puntos,temporizador) values ('dbdf5e1d-33df-5e8b-bc26-c021a813eed8','2fa17a3c-035a-50d7-afae-ed8fe3ba11fc','tf','El sáculo y el utrículo detectan exclusivamente la aceleración angular.','[{"text":"Verdadero","correct":false,"pregunta_imagen":"/juegos/assets/sentidos-saladin/s84-image247.png","explicacion":"El sáculo y el utrículo participan en el equilibrio estático y la aceleración lineal; los conductos semicirculares detectan la angular. Fuente: diapositiva 84."},{"text":"Falso","correct":true}]'::jsonb,false,7,1,60) on conflict(id) do update set tipo=excluded.tipo,texto=excluded.texto,opciones=excluded.opciones,multiple_correctas=excluded.multiple_correctas,orden=excluded.orden,puntos=excluded.puntos,temporizador=excluded.temporizador;
insert into public.evaluacion_preguntas (id,evaluacion_id,tipo,texto,opciones,multiple_correctas,orden,puntos,temporizador) values ('7af3994a-eaf5-5954-90a2-503ccb523da7','2fa17a3c-035a-50d7-afae-ed8fe3ba11fc','match','Relaciona las estructuras vestibulares con el movimiento que detectan.','[{"text":"Sáculo y utrículo","match":"Equilibrio estático y aceleración lineal","pregunta_imagen":"/juegos/assets/sentidos-saladin/s64-image199.png","explicacion":"El sistema vestibular distingue posición respecto a la gravedad, aceleración lineal y aceleración angular. Fuente: diapositiva 84."},{"text":"Conductos semicirculares","match":"Aceleración angular"}]'::jsonb,false,8,1,90) on conflict(id) do update set tipo=excluded.tipo,texto=excluded.texto,opciones=excluded.opciones,multiple_correctas=excluded.multiple_correctas,orden=excluded.orden,puntos=excluded.puntos,temporizador=excluded.temporizador;
insert into public.evaluacion_preguntas (id,evaluacion_id,tipo,texto,opciones,multiple_correctas,orden,puntos,temporizador) values ('8a2ecbee-fc66-5676-838d-e7d829be9551','2fa17a3c-035a-50d7-afae-ed8fe3ba11fc','ms','¿Qué detectan el sáculo y el utrículo?','[{"text":"Posición de la cabeza respecto a la gravedad","correct":true,"pregunta_imagen":"/juegos/assets/sentidos-saladin/s86-image252.png","explicacion":"El sáculo y el utrículo participan en el equilibrio estático y detectan aceleración lineal. Fuente: diapositiva 84."},{"text":"Aceleración en línea recta","correct":true},{"text":"Sabores","correct":false},{"text":"Colores","correct":false}]'::jsonb,true,9,1,60) on conflict(id) do update set tipo=excluded.tipo,texto=excluded.texto,opciones=excluded.opciones,multiple_correctas=excluded.multiple_correctas,orden=excluded.orden,puntos=excluded.puntos,temporizador=excluded.temporizador;
insert into public.evaluacion_preguntas (id,evaluacion_id,tipo,texto,opciones,multiple_correctas,orden,puntos,temporizador) values ('0400dd5f-21e3-5829-86c8-7cedc655a4dc','2fa17a3c-035a-50d7-afae-ed8fe3ba11fc','mc','¿Qué estructura del oído interno contiene el órgano de Corti y participa en la audición?','[{"text":"Iris","correct":false,"pregunta_imagen":"/juegos/assets/sentidos-saladin/s59-image186.png","explicacion":"La cóclea o caracol contiene el órgano de Corti, receptor de la audición. Fuente: diapositiva 65."},{"text":"Lengua","correct":false},{"text":"Cóclea o caracol","correct":true},{"text":"Cristalino","correct":false}]'::jsonb,false,10,1,60) on conflict(id) do update set tipo=excluded.tipo,texto=excluded.texto,opciones=excluded.opciones,multiple_correctas=excluded.multiple_correctas,orden=excluded.orden,puntos=excluded.puntos,temporizador=excluded.temporizador;
insert into public.evaluacion_preguntas (id,evaluacion_id,tipo,texto,opciones,multiple_correctas,orden,puntos,temporizador) values ('22b2438c-ad4a-5a64-a380-1803bdb9db72','2fa17a3c-035a-50d7-afae-ed8fe3ba11fc','match','Relaciona cada túnica del ojo con sus componentes.','[{"text":"Fibrosa","match":"Esclerótica y córnea","pregunta_imagen":"/juegos/assets/sentidos-saladin/s100-image284.png","explicacion":"La pared del globo ocular se organiza en túnicas fibrosa, vascular e interna. Fuente: diapositiva 100."},{"text":"Vascular","match":"Coroides, cuerpo ciliar e iris"},{"text":"Interna","match":"Retina"}]'::jsonb,false,11,1,90) on conflict(id) do update set tipo=excluded.tipo,texto=excluded.texto,opciones=excluded.opciones,multiple_correctas=excluded.multiple_correctas,orden=excluded.orden,puntos=excluded.puntos,temporizador=excluded.temporizador;
insert into public.evaluacion_preguntas (id,evaluacion_id,tipo,texto,opciones,multiple_correctas,orden,puntos,temporizador) values ('fa546b6e-8fcc-5c43-bb43-41c6fe4d6066','2fa17a3c-035a-50d7-afae-ed8fe3ba11fc','ms','Selecciona las estructuras que pertenecen a la túnica vascular.','[{"text":"Coroides","correct":true,"pregunta_imagen":"/juegos/assets/sentidos-saladin/s101-image288.png","explicacion":"La túnica vascular o úvea incluye coroides, cuerpo ciliar e iris; la córnea pertenece a la túnica fibrosa. Fuente: diapositiva 101."},{"text":"Cuerpo ciliar","correct":true},{"text":"Iris","correct":true},{"text":"Córnea","correct":false}]'::jsonb,true,12,1,60) on conflict(id) do update set tipo=excluded.tipo,texto=excluded.texto,opciones=excluded.opciones,multiple_correctas=excluded.multiple_correctas,orden=excluded.orden,puntos=excluded.puntos,temporizador=excluded.temporizador;
insert into public.evaluacion_preguntas (id,evaluacion_id,tipo,texto,opciones,multiple_correctas,orden,puntos,temporizador) values ('aece70ef-22d9-5353-8d1b-b7673d3952b1','2fa17a3c-035a-50d7-afae-ed8fe3ba11fc','mc','¿Qué cambio describe una catarata en la presentación?','[{"text":"Turbiedad del cristalino","correct":true,"pregunta_imagen":"/juegos/assets/sentidos-saladin/s105-image300.png","explicacion":"Una catarata es la aparición de turbiedad en el cristalino. Fuente: diapositiva 105."},{"text":"Aumento del número de conos","correct":false},{"text":"Rotación del globo ocular","correct":false},{"text":"Adaptación a la oscuridad","correct":false}]'::jsonb,false,13,1,60) on conflict(id) do update set tipo=excluded.tipo,texto=excluded.texto,opciones=excluded.opciones,multiple_correctas=excluded.multiple_correctas,orden=excluded.orden,puntos=excluded.puntos,temporizador=excluded.temporizador;
insert into public.evaluacion_preguntas (id,evaluacion_id,tipo,texto,opciones,multiple_correctas,orden,puntos,temporizador) values ('0dff4ac3-c04a-541c-9729-876984a49c8c','2fa17a3c-035a-50d7-afae-ed8fe3ba11fc','tf','El disco óptico produce un punto ciego porque carece de fotorreceptores.','[{"text":"Verdadero","correct":true,"pregunta_imagen":"/juegos/assets/sentidos-saladin/s108-image310.png","explicacion":"El disco óptico es la salida del nervio óptico y carece de fotorreceptores. Fuente: diapositiva 108."},{"text":"Falso","correct":false}]'::jsonb,false,14,1,60) on conflict(id) do update set tipo=excluded.tipo,texto=excluded.texto,opciones=excluded.opciones,multiple_correctas=excluded.multiple_correctas,orden=excluded.orden,puntos=excluded.puntos,temporizador=excluded.temporizador;
insert into public.evaluacion_preguntas (id,evaluacion_id,tipo,texto,opciones,multiple_correctas,orden,puntos,temporizador) values ('ef64e77e-a5f9-56b8-9d7a-c1374e4f63fe','2fa17a3c-035a-50d7-afae-ed8fe3ba11fc','ms','¿Qué estructuras o medios transparentes atraviesa la luz dentro del ojo?','[{"text":"Córnea","correct":true,"pregunta_imagen":"/juegos/assets/sentidos-saladin/s117-image332.png","explicacion":"Los componentes ópticos incluyen córnea, humor acuoso, cristalino y humor vítreo. Fuente: diapositiva 103."},{"text":"Cristalino","correct":true},{"text":"Humor vítreo","correct":true},{"text":"Huesecillos del oído","correct":false}]'::jsonb,true,15,1,60) on conflict(id) do update set tipo=excluded.tipo,texto=excluded.texto,opciones=excluded.opciones,multiple_correctas=excluded.multiple_correctas,orden=excluded.orden,puntos=excluded.puntos,temporizador=excluded.temporizador;
insert into public.evaluacion_preguntas (id,evaluacion_id,tipo,texto,opciones,multiple_correctas,orden,puntos,temporizador) values ('3006dbc3-78cd-571c-aca0-8b136a740e8f','2fa17a3c-035a-50d7-afae-ed8fe3ba11fc','match','Relaciona cada defecto visual con su descripción.','[{"text":"Miopía","match":"Los rayos se enfocan antes de alcanzar la retina","pregunta_imagen":"/juegos/assets/sentidos-saladin/s118-image336.png","explicacion":"La tabla de la presentación compara miopía, hipermetropía y astigmatismo por su mecanismo de desenfoque. Fuente: diapositiva 118."},{"text":"Hipermetropía","match":"El globo ocular es demasiado corto"},{"text":"Astigmatismo","match":"La curvatura corneal dificulta enfocar en distintos planos"}]'::jsonb,false,16,1,90) on conflict(id) do update set tipo=excluded.tipo,texto=excluded.texto,opciones=excluded.opciones,multiple_correctas=excluded.multiple_correctas,orden=excluded.orden,puntos=excluded.puntos,temporizador=excluded.temporizador;
insert into public.evaluacion_preguntas (id,evaluacion_id,tipo,texto,opciones,multiple_correctas,orden,puntos,temporizador) values ('50d49340-8dad-5a1d-a77a-139906741d2f','2fa17a3c-035a-50d7-afae-ed8fe3ba11fc','mc','¿Qué fotorreceptores permiten principalmente la visión con luz tenue?','[{"text":"Conos","correct":false,"pregunta_imagen":"/juegos/assets/sentidos-saladin/s134-image374.png","explicacion":"El sistema escotópico depende de los bastones y funciona con luz tenue. Fuente: diapositiva 132."},{"text":"Células gustativas","correct":false},{"text":"Células pilosas","correct":false},{"text":"Bastones","correct":true}]'::jsonb,false,17,1,60) on conflict(id) do update set tipo=excluded.tipo,texto=excluded.texto,opciones=excluded.opciones,multiple_correctas=excluded.multiple_correctas,orden=excluded.orden,puntos=excluded.puntos,temporizador=excluded.temporizador;
insert into public.evaluacion_preguntas (id,evaluacion_id,tipo,texto,opciones,multiple_correctas,orden,puntos,temporizador) values ('42ca4ec0-4c38-5cd0-b6e8-a3bda0e29335','2fa17a3c-035a-50d7-afae-ed8fe3ba11fc','tf','Los conos participan en la visión diurna y permiten una mayor agudeza visual que el sistema de bastones.','[{"text":"Verdadero","correct":true,"pregunta_imagen":"/juegos/assets/sentidos-saladin/s133-image371.png","explicacion":"La visión fotópica se basa en conos y presenta menor convergencia neural, lo que favorece la agudeza visual. Fuente: diapositiva 133."},{"text":"Falso","correct":false}]'::jsonb,false,18,1,60) on conflict(id) do update set tipo=excluded.tipo,texto=excluded.texto,opciones=excluded.opciones,multiple_correctas=excluded.multiple_correctas,orden=excluded.orden,puntos=excluded.puntos,temporizador=excluded.temporizador;
insert into public.evaluacion_preguntas (id,evaluacion_id,tipo,texto,opciones,multiple_correctas,orden,puntos,temporizador) values ('98195178-b98c-5820-a39b-9c4d2da1acea','2fa17a3c-035a-50d7-afae-ed8fe3ba11fc','ms','Selecciona las afirmaciones correctas sobre conos y bastones.','[{"text":"Los conos participan en la visión de los colores","correct":true,"pregunta_imagen":"/juegos/assets/sentidos-saladin/s126-image354.png","explicacion":"Conos y bastones son fotorreceptores de la retina. Los conos permiten visión del color; los bastones funcionan con luz tenue. Fuente: diapositiva 132."},{"text":"Los bastones ayudan a ver con luz tenue","correct":true},{"text":"Ambos se encuentran en la retina","correct":true},{"text":"Ambos son huesecillos del oído","correct":false}]'::jsonb,true,19,1,60) on conflict(id) do update set tipo=excluded.tipo,texto=excluded.texto,opciones=excluded.opciones,multiple_correctas=excluded.multiple_correctas,orden=excluded.orden,puntos=excluded.puntos,temporizador=excluded.temporizador;
insert into public.evaluacion_preguntas (id,evaluacion_id,tipo,texto,opciones,multiple_correctas,orden,puntos,temporizador) values ('9f1d594c-3413-58e5-b63a-e59f0cc8be6e','2fa17a3c-035a-50d7-afae-ed8fe3ba11fc','mc','¿En qué lóbulo se encuentra la corteza visual primaria donde ocurre la sensación visual consciente?','[{"text":"Frontal","correct":false,"pregunta_imagen":"/juegos/assets/sentidos-saladin/s4-image15.png","explicacion":"La irradiación óptica llega a la corteza visual primaria del lóbulo occipital. Fuente: diapositiva 138."},{"text":"Occipital","correct":true},{"text":"Temporal","correct":false},{"text":"Parietal","correct":false}]'::jsonb,false,20,1,60) on conflict(id) do update set tipo=excluded.tipo,texto=excluded.texto,opciones=excluded.opciones,multiple_correctas=excluded.multiple_correctas,orden=excluded.orden,puntos=excluded.puntos,temporizador=excluded.temporizador;
